// parsing helpers extracted from legacy/helpers.ts
import type { DurationUnit } from '../generated/types';

const UNIT_MS: Record<DurationUnit, number> = {
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
  d: 86_400_000,
};

/** Parses "1h30m", "250ms", "2d" into milliseconds. */
export function parseDuration(input: string): number {
  const matches = input.trim().matchAll(/(\d+(?:\.\d+)?)(ms|s|m|h|d)/g);
  let total = 0;
  let seen = false;
  for (const m of matches) {
    seen = true;
    total += parseFloat(m[1]) * UNIT_MS[m[2] as DurationUnit];
  }
  if (!seen) throw new Error(`invalid duration: ${input}`);
  return total;
}

